/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_DsTproverkau2ePeremennaya *dm_DsTproverkau2ePeremennaya_copy(const dm_DsTproverkau2ePeremennaya *d) {
    dm_DsTproverkau2ePeremennaya *r = dm_DsTproverkau2ePeremennaya_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_DsTproverkau2ePeremennaya_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = dan_str_share(d->keys[e]); r->vals[m] = dt_proverkau2ePeremennaya_share(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_DsTproverkau2ePeremennaya_reindex(r);
    return r;
}
static dm_DsTproverkau2ePeremennaya *dm_DsTproverkau2ePeremennaya_mut(dm_DsTproverkau2ePeremennaya **pp) {
    dm_DsTproverkau2ePeremennaya *d = *pp;
    if (d->h.rc > 1) { dm_DsTproverkau2ePeremennaya *r = dm_DsTproverkau2ePeremennaya_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
static dan_str dm_DsTproverkau2ePeremennaya_str(const dm_DsTproverkau2ePeremennaya *d) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "{");
    bool first = true;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        if (!first) dan_buf_add(&b, ", ");
        first = false;
        dan_buf_add(&b, dan_quote_str(d->keys[e]));
        dan_buf_add(&b, ": ");
        dan_buf_add(&b, dt_proverkau2ePeremennaya_str(d->vals[e]));
    }
    dan_buf_add(&b, "}");
    return dan_buf_str(&b);
}
static void dm_DsTproverkau2ePeremennaya_write(const dm_DsTproverkau2ePeremennaya *d) { fputs(dm_DsTproverkau2ePeremennaya_str(d), stdout); }


static bool dm_DsTproverkau2ePeremennaya_eq(const dm_DsTproverkau2ePeremennaya *x, const dm_DsTproverkau2ePeremennaya *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_DsTproverkau2ePeremennaya_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        dt_proverkau2ePeremennaya a = x->vals[e]; dt_proverkau2ePeremennaya b = y->vals[f];
        if (!(dt_proverkau2ePeremennaya_eq(a, b))) return false;
    }
    return true;
}


