struct dm_DsLTporozhdenieu2ePotreblyaemyj { dan_hdr h; int64_t len, n, cap, slots; dan_str *keys; dl_LTporozhdenieu2ePotreblyaemyj* *vals; uint64_t *hashes; bool *alive; int64_t *index; };

